/**
 * The Worker entry (wrangler.jsonc `main`). OpenNext's generated `worker.js` handles `fetch`
 * only; this adds the daily Cron Trigger (`scheduled`) and the job queue consumer (`queue`),
 * and wraps all three with Sentry (ADR 0002, issues #9 and #10).
 *
 * Only this file imports @sentry/cloudflare at runtime: the SDK needs `cloudflare:workers`,
 * which Node (next dev, Playwright, Vitest) doesn't have. Tests import daily.ts and queue.ts.
 */
import { captureException, withSentry } from "@sentry/cloudflare";
// @ts-expect-error: generated by `opennextjs-cloudflare build`; wrangler resolves it at deploy.
import openNext from "../../.open-next/worker.js";
import { createDb } from "../db";
import {
  createLogger,
  installConsoleGuard,
  registerErrorReporter,
  reportError,
  sentryOptions,
  type SentryEnv,
} from "../modules/observability";
import { DAILY_JOBS, runDailyJobs } from "./daily";
import { handleQueueBatch, QUEUE_HANDLERS, type JobMessage } from "./queue";

registerErrorReporter((error, tags) => captureException(error, { tags }));
// A cron or queue invocation may never load the Next.js server, whose instrumentation installs
// the guard for requests.
installConsoleGuard();

type Env = CloudflareEnv & SentryEnv;

const handler: ExportedHandler<Env, JobMessage> = {
  fetch: (request, env, ctx) =>
    (openNext as ExportedHandler<CloudflareEnv>).fetch!(request, env, ctx),

  async scheduled(controller, env) {
    const log = createLogger().child({ cron: controller.cron });
    const openDb = () => createDb(env.HYPERDRIVE.connectionString);
    const failed = await runDailyJobs(DAILY_JOBS, { openDb, log, report: reportError });
    log.info("jobs.daily_finished", { jobs: DAILY_JOBS.length, failed: failed.length });
  },

  async queue(batch, env) {
    const log = createLogger().child({ queue: batch.queue });
    const openDb = () => createDb(env.HYPERDRIVE.connectionString);
    await handleQueueBatch(batch.messages, QUEUE_HANDLERS, { openDb, log, report: reportError });
  },
};

export default withSentry((env: Env) => sentryOptions(env), handler);
